package com.rustraid.service
import android.app.*;import android.content.*;import android.media.*;import android.os.*;import androidx.core.app.NotificationCompat
class AlarmService:Service(){private var player:MediaPlayer?=null; override fun onStartCommand(i:Intent?,f:Int,id:Int):Int{val nm=getSystemService(NotificationManager::class.java);nm.createNotificationChannel(NotificationChannel("raid","Raid alerts",NotificationManager.IMPORTANCE_HIGH));startForeground(4,NotificationCompat.Builder(this,"raid").setSmallIcon(android.R.drawable.ic_dialog_alert).setContentTitle("RAID ACTIVE").setContentText("Open Rust Raid Alarm to acknowledge").build());val am=getSystemService(AudioManager::class.java);am.setStreamVolume(AudioManager.STREAM_ALARM,am.getStreamMaxVolume(AudioManager.STREAM_ALARM),0);player=MediaPlayer.create(this,com.rustraid.R.raw.alarm_defcon)?.apply{isLooping=true;start()};(getSystemService(Vibrator::class.java)).vibrate(VibrationEffect.createWaveform(longArrayOf(0,500,200,500),0));return START_NOT_STICKY};override fun onBind(i:Intent?)=null;override fun onDestroy(){player?.release();(getSystemService(Vibrator::class.java)).cancel();super.onDestroy()};companion object{fun intent(c:Context)=Intent(c,AlarmService::class.java)}}
